**`/home/kara/chring/ring.go`** — the consistent hash ring:

```go
package chring

import (
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"sort"
	"sync"
)

// VNode represents a single virtual node on the hash ring.
type VNode struct {
	Hash uint64 // position on the ring (0..2^64-1)
	Node string // owning physical node
}

type nodeInfo struct {
	name   string
	weight float64
}

// Ring is a goroutine-safe consistent hash ring.
type Ring struct {
	mu       sync.RWMutex
	nodes    map[string]*nodeInfo
	vnodes   []VNode              // sorted slice of all virtual nodes
	replicas int                  // base vnodes per unit weight
}

// New creates a Ring with the given base replication factor.
func New(replicas int) *Ring {
	if replicas < 1 {
		replicas = 1
	}
	return &Ring{
		nodes:    make(map[string]*nodeInfo),
		vnodes:   make([]VNode, 0),
		replicas: replicas,
	}
}

func hashKey(key []byte) uint64 {
	h := sha256.Sum256(key)
	return binary.BigEndian.Uint64(h[:8])
}

// AddNode inserts a physical node with the given weight.
func (r *Ring) AddNode(name string, weight float64) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.nodes[name]; ok {
		return
	}
	r.nodes[name] = &nodeInfo{name: name, weight: weight}
	count := int(float64(r.replicas) * weight)
	if count < 1 {
		count = 1
	}
	existing := make(map[uint64]bool, len(r.vnodes))
	for _, vn := range r.vnodes {
		existing[vn.Hash] = true
	}
	newVNodes := make([]VNode, 0, count)
	for i := 0; i < count; i++ {
		s := fmt.Sprintf("%s:%d", name, i)
		h := hashKey([]byte(s))
		for existing[h] {
			s = fmt.Sprintf("%s:%d_%d", name, i, h)
			h = hashKey([]byte(s))
		}
		existing[h] = true
		newVNodes = append(newVNodes, VNode{Hash: h, Node: name})
	}
	r.vnodes = append(r.vnodes, newVNodes...)
	sort.Slice(r.vnodes, func(i, j int) bool {
		return r.vnodes[i].Hash < r.vnodes[j].Hash
	})
}

// RemoveNode removes a physical node and all its virtual nodes.
func (r *Ring) RemoveNode(name string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.nodes[name]; !ok {
		return
	}
	delete(r.nodes, name)

	filtered := make([]VNode, 0, len(r.vnodes))
	for _, vn := range r.vnodes {
		if vn.Node != name {
			filtered = append(filtered, vn)
		}
	}
	r.vnodes = filtered
}

// Get returns the physical node responsible for the given key.
// Uses bisection (binary search) over the sorted vnode ring for O(log N) lookup.
func (r *Ring) Get(key string) (string, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	if len(r.vnodes) == 0 {
		return "", false
	}
	h := hashKey([]byte(key))
	idx := sort.Search(len(r.vnodes), func(i int) bool {
		return r.vnodes[i].Hash >= h
	})
	if idx == len(r.vnodes) {
		idx = 0
	}
	return r.vnodes[idx].Node, true
}
```

**Key design decisions:**

| Property | Mechanism |
|---|---|
| **O(log N) lookup** | Bisection via `sort.Search` over a sorted `[]VNode` |
| **SHA-256 collision resistance** | On collision, append the colliding hash and re-hash until unique |
| **Weighted nodes** | Each node gets `weight * replicas` independent vnodes |
| **Minimal redistribution** | Removing a node only removes its vnodes; adding only inserts new ones. Only keys near the added/removed vnodes shift — O(1/n) fraction affected |
| **Thread safety** | `sync.RWMutex` — reads (`Get`) use RLock, writes (`AddNode`/`RemoveNode`) use exclusive Lock |
| **Online rebalancing** | `AddNode`/`RemoveNode` can be called at any time with no global state |

